{\pard \ql \f0 \fs24 \sa180 \li0 \fi0 Held-note tracking, an input gate and a note-off/CC64 flush, for clean live patch switching. Used by StageRig, but useful on its own anywhere a MIDI stream needs to be stopped without leaving notes hanging.\par}
}

{\rtf1\ansi\deff0{\fonttbl{\f0 \fswiss Helvetica;}{\f1 \fmodern Courier;}}
{\colortbl;\red255\green0\blue0;\red0\green0\blue255;}
